script:
frappe.ui.form.on('Organization', {
    refresh: function(frm) {
        // ตรวจสอบว่ามีการเลือกจังหวัดหรือไม่
        if (frm.doc.province) {
            // ดึงข้อมูลอำเภอเมื่อมีการเลือกจังหวัด
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Amphoe",
                    filters: {
                        province_th: frm.doc.province
                    },
                    fields: ["amphoe_th"]
                },
                callback: function(r) {
                    if (r.message) {
                        let amphoe_options = r.message.map(d => d.amphoe_th);
                        // อัปเดตตัวเลือกในช่องอำเภอ
                        frm.set_df_property('amphoe', 'options', amphoe_options.join('\n'));
                        frm.refresh_field('amphoe');
                    }
                }
            });
        }

        // ตรวจสอบว่ามีการเลือกจังหวัดและอำเภอหรือไม่
        if (frm.doc.province && frm.doc.amphoe) {
            // ดึงข้อมูลตำบลเมื่อมีการเลือกอำเภอ
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Tambon",
                    filters: {
                        province_th: frm.doc.province,
                        amphoe_th: frm.doc.amphoe
                    },
                    fields: ["tambon_th"]
                },
                callback: function(r) {
                    if (r.message) {
                        let tambon_options = r.message.map(d => d.tambon_th);
                        // อัปเดตตัวเลือกในช่องตำบล
                        frm.set_df_property('tambon', 'options', tambon_options.join('\n'));
                        frm.refresh_field('tambon');
                    }
                }
            });
        }
    },
    province: function(frm) {
        if (frm.doc.province) {
            // ดึงข้อมูลอำเภอเมื่อมีการเลือกจังหวัด
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Amphoe",
                    filters: {
                        province_th: frm.doc.province
                    },
                    fields: ["amphoe_th"]
                },
                callback: function(r) {
                    if (r.message) {
                        let amphoe_options = r.message.map(d => d.amphoe_th);
                        // อัปเดตตัวเลือกในช่องอำเภอ
                        frm.set_df_property('amphoe', 'options', amphoe_options.join('\n'));
                        frm.refresh_field('amphoe');
                    }
                }
            });
        } else {
            // ล้างค่าช่อง amphoe, tambon และ postal_code เมื่อ province เป็นค่าว่าง
            frm.set_value('amphoe', '');
            frm.set_value('tambon', '');
            frm.set_value('postal_code', '');
        }
    },
    amphoe: function(frm) {
        if (frm.doc.province && frm.doc.amphoe) {
            // ดึงข้อมูลตำบลเมื่อมีการเลือกอำเภอ
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Tambon",
                    filters: {
                        province_th: frm.doc.province,
                        amphoe_th: frm.doc.amphoe
                    },
                    fields: ["tambon_th"]
                },
                callback: function(r) {
                    if (r.message) {
                        let tambon_options = r.message.map(d => d.tambon_th);
                        // อัปเดตตัวเลือกในช่องตำบล
                        frm.set_df_property('tambon', 'options', tambon_options.join('\n'));
                        frm.refresh_field('tambon');
                    }
                }
            });
        } else {
            // ล้างค่าช่อง tambon และ postal_code เมื่อ amphoe เป็นค่าว่าง
            frm.set_value('tambon', '');
            frm.set_value('postal_code', '');
        }
    },
    tambon: function(frm) {
        if (frm.doc.province && frm.doc.amphoe && frm.doc.tambon) {
            // ดึงข้อมูลรหัสไปรษณีย์เมื่อมีการเลือกตำบล
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Tambon",
                    filters: {
                        province_th: frm.doc.province,
                        amphoe_th: frm.doc.amphoe,
                        tambon_th: frm.doc.tambon
                    },
                    fieldname: ["postal_code"]
                },
                callback: function(r) {
                    if (r.message) {
                        frm.set_value('postal_code', r.message.postal_code);
                    }
                }
            });
        } else {
            // ล้างค่าช่อง postal_code เมื่อ tambon เป็นค่าว่าง
            frm.set_value('postal_code', '');
        }
    }
});


frappe.ui.form.on('Organization', {
    before_save: function(frm) {
        // Retrieve the values from the form fields
        var no = frm.doc.no || "";
        var moo = frm.doc.moo ? 'ม.' + frm.doc.moo : "";
        var road = frm.doc.road ? 'ถ.' + frm.doc.road : "";
        var soi = frm.doc.soi ? 'ซ.' + frm.doc.soi : "";
        var tambon = frm.doc.tambon || "";
        var amphoe = frm.doc.amphoe || "";
        var province = frm.doc.province || "";
        var postal_code = frm.doc.postal_code || "";

        // Construct the address string based on the province
        var address = no + " " + moo;
        if (soi || road) {
            address += " " + road + " " + soi;
        }
        
        if (province === 'กรุงเทพมหานคร') {
            address += " " + tambon;
            if (amphoe) {
                address += ' เขต' + amphoe;
            }
            address += " " + province + " " + postal_code;
        } else {
            if (tambon) {
                address += ' ต.' + tambon;
            }
            if (amphoe) {
                address += ' อ.' + amphoe;
            }
            if (province) {
                address += ' จ.' + province;
            }
            address += " " + postal_code;
        }

        // Update the address field
        frm.set_value('address', address.trim());
    }
});

//ดึงตำบลและรหัสไปรษณีย์มาแสดงเมื่อเลือกอำเภอ
frappe.ui.form.on('Distributor', {
    refresh: function(frm) {
        set_queries(frm);
    },
    province: function(frm) {
        frm.set_value('amphoe_copy', "");
        frm.set_value('tambon_copy', "");
        frm.set_value('postal_code', "");
    },
    amphoe: function(frm) {
        frm.set_value('tambon', "");
        frm.set_value('postal_code', "");
    },
    tambon: function(frm) {
        if (frm.doc.tambon) {
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Tambon",
                    filters: {
                        name: frm.doc.tambon_copy
                    },
                    fieldname: "postal_code"
                },
                callback: function(r) {
                    if (r.message) {
                        frm.set_value('postal_code', r.message.postal_code);
                    }
                }
            });
        } else {
            frm.set_value('postal_code', "");
        }
    }
});

// ฟังก์ชันสำหรับกรองตัวเลือก
function set_queries(frm) {
    frm.set_query("amphoe_copy", function() {
        return {
            filters: { province_th: frm.doc.province }
        };
    });

    frm.set_query("tambon_copy", function() {
        return {
            filters: {
                province_th: frm.doc.province,
                amphoe_th: frm.doc.amphoe
            }
        };
    });
}




