// mandatory ช่อง Check ให้เลิอกอย่างน้อย 1 ช่อง 
frappe.ui.form.on('Glass Kids', {
    validate: function(frm) {
        let is_checked = false;

        frm.doc.glass_kids_table.forEach(function(row) {
            if (row.glass === 1 || row.check_eyes === 1) {
                is_checked = true;
            }
        });

        if (!is_checked) {
            frappe.msgprint(__('กรุณาเลือกรายการตรวจ'));
            frappe.validated = false;
        }
    }
});


//เมื่อกด Save แล้ว ช่อง HNกับชื่อ-นามสกุล จะแสดง
frappe.ui.form.on("Glass Kids", "validate", function(frm){
    cur_frm.set_value("fullname", cur_frm.doc.namef + " " + cur_frm.doc.lastname);
});


frappe.ui.form.on("Glass Kids", "after_save", function(frm){
    cur_frm.set_value("hn", cur_frm.doc.name);
});

//เบอร์โทร
frappe.ui.form.on('Glass Kids', {
    validate: function(frm) {
        if (frm.doc.phone_numbers && frm.doc.phone_numbers.toString().length < 9) {
            frappe.msgprint(__('กรุณากรอกหมายเลขโทรศัพท์ที่ถูกต้องอย่างน้อย 9 ตัว'));
            frappe.validated = false;
        }
    },
    refresh: function(frm) {
        // Add event listener to the phone number field
        frm.fields_dict['phone_numbers'].df.onchange = function() {
            var phoneInput = frm.fields_dict['phone_numbers'].input;
            if (phoneInput.value.length > 10) {
                phoneInput.value = phoneInput.value.slice(0, 10); // Limit to 10 characters
            }
        };
    }
});

//บัตรปชช
frappe.ui.form.on('Glass Kids', {
    validate: function(frm) {
        if (!verifyPeopleID(frm.doc.id_card)) {
            frappe.msgprint(__('หมายเลขบัตรประชาชนผิดพลาด กรุณาตรวจสอบใหม่อีกครั้ง'));
            frappe.validated = false;
            frm.get_field("id_card").$input.css({"border": "1px solid red"});
        } else {
            // ตรวจสอบว่ามีเลขบัตรประชาชนซ้ำหรือไม่
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Glass Kids',
                    filters: {
                        id_card: frm.doc.id_card,
                        name: ['!=', frm.doc.name]
                    },
                    limit_page_length: 1
                },
                callback: function(r) {
                    if (r.message && r.message.length > 0) {
                        frappe.msgprint(__('หมายเลขบัตรประชาชนซ้ำ กรุณาตรวจสอบใหม่อีกครั้ง'));
                        frappe.validated = false;
                        frm.get_field("id_card").$input.css({"border": "1px solid red"});
                    } else {
                        frm.get_field("id_card").$input.css({"border": ""});
                    }
                }
            });
        }
    },
    id_card: function(frm) {
        if (verifyPeopleID(frm.doc.id_card)) {
            frm.get_field("id_card").$input.css({"border": ""});
        } else {
            frm.get_field("id_card").$input.css({"border": "1px solid red"});
        }
    }
});


function verifyPeopleID(PID) {
    // ตรวจสอบว่าทุก ๆ ตัวอักษรเป็นตัวเลข
    if (!/^\d+$/.test(PID)) {
        return false;
    }
    // ตรวจสอบว่าข้อมูลมีทั้งหมด 13 ตัวอักษร
    if (PID.trim().length !== 13) {
        return false;
    }
    var sumValue = 0;
    // คำนวณค่า checksum
    for (var i = 0; i < PID.length - 1; i++) {
        sumValue += parseInt(PID[i]) * (13 - i);
    }
    var v = (11 - (sumValue % 11)) % 10;
    // ตรวจสอบว่าหมายเลขสุดท้ายตรงกับค่า checksum ที่คำนวณได้
    return PID[12] == v.toString();
}


//ดึงข้อมูลอำเภอ ตำบล รหัสไปรษณีย์
frappe.ui.form.on('Glass Kids', {
    refresh: function(frm) {
        // ตรวจสอบว่ามีการเลือกจังหวัดหรือไม่
        if (frm.doc.province) {
            // ดึงข้อมูลอำเภอเมื่อมีการเลือกจังหวัด
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Amphoe",
                    filters: {
                        province_th: frm.doc.province
                    },
                    fields: ["amphoe_th"],
                    order_by: "amphoe_th asc",
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        let amphoe_options = r.message.map(d => d.amphoe_th);
                        // อัปเดตตัวเลือกในช่องอำเภอ
                        frm.set_df_property('amphoe', 'options', amphoe_options.join('\n'));
                        frm.refresh_field('amphoe');
                    }
                }
            });
        }
        // ตรวจสอบว่ามีการเลือกจังหวัดและอำเภอหรือไม่
        if (frm.doc.province && frm.doc.amphoe) {
            // ดึงข้อมูลตำบลเมื่อมีการเลือกอำเภอ
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Tambon",
                    filters: {
                        province_th: frm.doc.province,
                        amphoe_th: frm.doc.amphoe
                    },
                    fields: ["tambon_th"],
                    order_by: "tambon_th asc",
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        let tambon_options = r.message.map(d => d.tambon_th);
                        // อัปเดตตัวเลือกในช่องตำบล
                        frm.set_df_property('tambon', 'options', tambon_options.join('\n'));
                        frm.refresh_field('tambon');
                    }
                }
            });
        }
    },
    province: function(frm) {
        if (frm.doc.province) {
            // ดึงข้อมูลอำเภอเมื่อมีการเลือกจังหวัด
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Amphoe",
                    filters: {
                        province_th: frm.doc.province
                    },
                    fields: ["amphoe_th"],
                    order_by: "amphoe_th asc",
                    limit_page_length: 100
                },
                callback: function(r) {
