frappe.ui.form.on('Glass Kids', {
    before_save: function(frm) {
        // Retrieve the values from the form fields
        var house_no = frm.doc.house_no || "";
        var moo = frm.doc.moo ? 'ม.' + frm.doc.moo : "";
        var road = frm.doc.road ? 'ถ.' + frm.doc.road : "";
        var soi = frm.doc.soi ? 'ซ.' + frm.doc.soi : "";
        var tambon = frm.doc.tambon || "";
        var amphoe = frm.doc.amphoe || "";
        var province = frm.doc.province || "";
        var postal_code = frm.doc.postal_code || "";

        // Construct the address string
        var address = house_no + " " + moo;
        if (soi || road) {
            address += " " + road + " " + soi;
        }

        // Append address components based on the availability of values
        if (province === 'กรุงเทพมหานคร') {
            address += " " + tambon;
            if (amphoe) {
                address += ' เขต' + amphoe;
            }
            address += " " + province + " " + postal_code;
        } else {
            if (tambon) {
                address += ' ต.' + tambon;
            }
            if (amphoe) {
                address += ' อ.' + amphoe;
            }
            if (province) {
                address += ' จ.' + province;
            }
            address += " " + postal_code;
        }

        // Update the address field
        frm.set_value('address', address.trim());
    }
});


frappe.ui.form.on('Glass Kids', {
    validate: function(frm) {
        // รับค่าวันเกิด
        var bithdate = frm.doc.bithdate;
        
        if (bithdate) {
            // แปลงวันเกิดเป็นวัตถุของ JavaScript Date
            var bithdate = new Date(bithdate);

            // ดึงข้อมูลวันที่ปัจจุบัน
            var currentDate = new Date();

            // คำนวณอายุในปี
            var years = currentDate.getFullYear() - bithdate.getFullYear();
            var months = currentDate.getMonth() - bithdate.getMonth();
            var days = currentDate.getDate() - bithdate.getDate();
            
            if (days < 0) {
                months--;
                days += new Date(currentDate.getFullYear(), currentDate.getMonth(), 0).getDate();
            }
            
            if (months < 0) {
                years--;
                months += 12;
            }

            // อัพเดทอายุใน form
            frm.set_value('age', years);
            frm.set_value('month', months);
            frm.set_value('day', days);
        } else {
            // ถ้าไม่มีข้อมูลวันเกิด, ตั้งค่า fields 'age_years', 'age_months', 'age_days' เป็นช่องว่าง
            frm.set_value('age', "");
            frm.set_value('month', "");
            frm.set_value('day', "");
        }
    }
});


// สูตรกำหนดการ Add Row ตามเงื่อนไข 
frappe.ui.form.on('Glass Kids', {
    refresh: function (frm) {
        frm.fields_dict['glass_kids_table'].grid.add_new_row = function () {
            let today = frappe.datetime.get_today(); // Today's date in YYYY-MM-DD format
            let today_date = new Date(today); // Convert to Date object for comparison
            let table = frm.doc.glass_kids_table || [];
            let row_exists = table.some(row => row.posting_date === today);

            if (row_exists) {
                frappe.msgprint({
                    message: '<span style="color: red;">' +
                        __('ไม่สามารถออก Visit ได้เนื่องจากวันนี้ได้ออก Visit ไปแล้ว กรุณาตรวจสอบข้อมูลอีกครั้ง') +
                        '</span>',
                    indicator: 'red'
                });
                return;
            }

            // กำหนด current_year จากปีปัจจุบัน
            let current_year = new Date().getFullYear();

            // Adjust fiscal year filter based on today
            let fiscal_year_filter = today_date >= new Date(current_year + '-10-01') 
                ? current_year.toString() 
                : (current_year - 1).toString();

            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Fiscal Years',
                    fields: ['name', 'fiscal_years_start', 'fiscal_years_end'],
                    filters: {
                        'fiscal_years_start': ['<=', today],
                        'fiscal_years_end': ['>=', today]
                    }
                },
                callback: function (response) {
                    if (response.message && response.message.length > 0) {
                        let fiscal_years = response.message[0];
                        let fiscal_years_start = new Date(fiscal_years.fiscal_years_start);
                        let fiscal_years_end = new Date(fiscal_years.fiscal_years_end);

                        if (today_date >= fiscal_years_start && today_date <= fiscal_years_end) {
                            let fiscal_year_thai = (parseInt(fiscal_years.name) + 543).toString();
                            frappe.msgprint({
                                message: '<span style="color: green;">' +
                                    __('อยู่ในช่วงปีงบประมาณ (' + fiscal_year_thai + ')') +
                                    '</span>',
                                indicator: 'blue'
                            });

                            // Add new row
                            let new_row = frappe.model.add_child(frm.doc, 'Glass Kids Table', 'glass_kids_table');
                            new_row.id_card = frm.doc.id_card;
                            new_row.fiscal_years = fiscal_years.name;
                            new_row.posting_date = today; // Set today's date
                            frm.refresh_field('glass_kids_table');
                        } else {
                            frappe.msgprint({
                                message: '<span style="color: red;">' +
                                    __('ไม่สามารถลงทะเบียนออก Visit ได้เนื่องจากไม่ได้อยู่ในปีงบประมาณ (' + fiscal_year_thai + ') กรุณาตรวจสอบข้อมูลอีกครั้ง') +
                                    '</span>',
                                indicator: 'red'
                            });
                        }
                    } else {
                        frappe.msgprint({
                            message: '<span style="color: red;">' +
                                __('ไม่สามารถดึงข้อมูลปีงบประมาณได้ กรุณาติดต่อไอที') +
                                '</span>',
                            indicator: 'red'
                        });
                    }
                }
            });
        }
    }
});

