frappe.ui.form.on('Purchase Orders', {
    before_save: async function(frm) {
        if (!frm.doc.test) {
            let next_number = await get_next_po_number();
            let today = new Date();
            let year = today.getFullYear();
            let month = String(today.getMonth() + 1).padStart(2, '0');
            frm.set_value('test', `PO${year}${month}${next_number}`);
        }
    }
});

async function get_next_po_number() {
    return new Promise((resolve, reject) => {
        frappe.call({
            method: "erpnext.purchase_orders.get_next_po_number",  // เปลี่ยนเป็น path ที่ถูกต้อง
            callback: function(r) {
                if (r.message) {
                    resolve(r.message); // คืนค่าเลขที่ถูกต้อง
                } else {
                    reject("Error fetching PO number");
                }
            }
        });
    });
}

