                        "pr": frm.doc.pr,
                        "wf_po_state": ["in", ["ร่างเอกสาร", "เสร็จสิ้น"]] // ตรวจสอบสถานะ "ร่างเอกสาร" หรือ "เสร็จสิ้น"
                    },
                    fields: ["name"]
