frappe.ui.form.on('Upload Type', {
    onload: function(frm) {
        let previousData = [];

        function fetchVisitData() {
            frappe.call({
                method: "erpnext.Upload_Type.fetch_tbl_upload_type",
                callback: function(r) {
                    if (r.message) {
                        let newData = r.message;

                        // ตรวจสอบว่าข้อมูลมีการเปลี่ยนแปลงหรือไม่
                        if (JSON.stringify(previousData) !== JSON.stringify(newData)) {
                            if (newData.length > 0) {
                                newData.forEach(function(row) {
                                    // ตรวจสอบว่ามี id_key_type นี้อยู่ในระบบหรือไม่
                                    frappe.call({
                                        method: "frappe.client.get_list",
                                        args: {
                                            doctype: "Upload Type",
                                            filters: {
                                                id_key_type: row.id_key_type
                                            },
                                            fields: ["name"]
                                        },
                                        callback: function(response) {
                                            if (response.message.length > 0) {
                                                // ถ้ามี id_key_type นี้อยู่แล้ว
                                                console.warn('Duplicate id_key_type:', row.id_key_type);
                                            } else {
                                                // ถ้าไม่มี id_key_type นี้อยู่ สร้างเอกสารใหม่
                                                frappe.call({
                                                    method: "frappe.client.insert",
                                                    args: {
                                                        doc: {
                                                            doctype: "Upload Type",
                                                            id_key_type: row.id_key_type,
                                                            name_type: row.name_type
                                                        }
                                                    },
                                                    callback: function(response) {
                                                        if (response.exc) {
                                                            console.error('Error:', response.exc);
                                                        } else {
                                                            console.log('Document created successfully');
                                                        }
                                                    },
                                                    error: function(err) {
                                                        console.error('Error:', err);
                                                    }
                                                });
                                            }
                                        },
                                        error: function(err) {
                                            console.error('Error checking duplicate id_key_type:', err);
                                        }
                                    });
                                });
                            }

                            // อัพเดท previousData
                            previousData = newData;
                        }
                    }
                },
                error: function(err) {
                    console.error('Error fetching data:', err);
                }
            });
        }

        // ตั้งค่า polling ให้ดึงข้อมูลทุก 5 วินาที
        setInterval(fetchVisitData, 5000); // ปรับเวลาเป็น 5 วินาที
    }
});

