frappe.ui.form.on('Reserve Meeting Room', {
    before_submit: function(frm) {
        if (frm.doc.start_datetime && frm.doc.end_datetime && frm.doc.meeting_room) {
            // เช็คว่าช่วงเวลาเริ่มต้นและสิ้นสุดไม่เท่ากัน
            if (frm.doc.start_datetime === frm.doc.end_datetime) {
                frappe.msgprint({
                    message: __('ไม่สามารถจองในช่วงเวลา (เริ่มและสิ้นสุดเป็นเวลาเดียวกัน) ได้ กรุณาระบุเวลาใหม่อีกครั้ง'),
                    indicator: 'red'
                });
                frappe.validated = false;
                return;
            }

            // เช็คว่าเวลาสิ้นสุดมากกว่าเวลาเริ่มต้น
            if (frm.doc.end_datetime <= frm.doc.start_datetime) {
                frappe.msgprint({
                    message: __('วัน/เวลาสิ้นสุดต้องมากกว่าวัน/เวลาเริ่มต้น กรุณาระบุวัน/เวลาใหม่อีกครั้ง'),
                    indicator: 'red'
                });
                frappe.validated = false;
                return;
            }

            // เช็คห้องประชุมที่ซ้ำกัน
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Reserve Meeting Room',
                    filters: [
                        ['meeting_room', '=', frm.doc.meeting_room],
                        ['start_datetime', '<', frm.doc.end_datetime],
                        ['end_datetime', '>', frm.doc.start_datetime],
                        ['docstatus', '=', 1] // ตรวจสอบเฉพาะเอกสารที่ถูก submit แล้ว
                    ],
                    fields: ['name', 'start_datetime', 'end_datetime'],
                    limit_page_length: 1 // จำกัดผลลัพธ์
                },
                async: false,
                callback: function(r) {
                    if (r.message && r.message.length > 0) {
                        let conflicting_reservation = r.message[0];
                        let existing_start_datetime = conflicting_reservation.start_datetime;
                        let existing_end_datetime = conflicting_reservation.end_datetime;

                        frappe.msgprint({
                            message: __('ช่วงเวลานี้มีการจองห้องประชุม "{0}" อยู่แล้ว ({1} ถึง {2}) กรุณาระบุเวลาใหม่อีกครั้ง', 
                            [frm.doc.meeting_room, formatDateTime(existing_start_datetime), formatDateTime(existing_end_datetime)]),
