                    }
                }
            });
        }
    }
});

// ฟังก์ชันสำหรับฟอร์แมตวันที่และเวลา
function formatDateTime(datetime) {
    // แปลง datetime เป็น object วันที่
    let date = new Date(datetime);
    // ฟอร์แมตวันที่เป็นแบบ "วัน เดือน ปี"
    let day = date.getDate();
    let month = date.toLocaleString('th-TH', { month: 'long' });
    let year = date.getFullYear() + 543; // แปลงปีให้เป็น พ.ศ.
    let hours = date.getHours().toString().padStart(2, '0'); // ฟอร์แมตชั่วโมง
    let minutes = date.getMinutes().toString().padStart(2, '0'); // ฟอร์แมตนาที
    // สร้าง string สำหรับเวลาที่ฟอร์แมต
    let time = `${hours}:${minutes} น.`; 

    return `${day} ${month} ${year}, ${time}`;
}





