frappe.ui.form.on('IT Support', {
    finish_date: function(frm) {
        calculate_period_and_time_used(frm);
    },
    operation_date: function(frm) {
        calculate_period_and_time_used(frm);
    },
    finish_time: function(frm) {
        calculate_period_and_time_used(frm);
    },
    operation_time: function(frm) {
        calculate_period_and_time_used(frm);
    }
});

function calculate_period_and_time_used(frm) {
    // คำนวณจำนวนวัน
    let days_difference = 0;
    if (frm.doc.finish_date && frm.doc.operation_date) {
        var finish_date = new Date(frm.doc.finish_date);
        var operation_date = new Date(frm.doc.operation_date);
        var time_difference = finish_date - operation_date;
        days_difference = Math.floor(time_difference / (1000 * 3600 * 24));
        frm.set_value('period', days_difference || 0); // ถ้าเป็น 0 ก็แสดง 0
    } else {
        frm.set_value('period', 0); // ถ้าไม่มีค่าก็แสดง 0
    }

    // คำนวณเวลาที่ใช้เป็นนาที
    if (frm.doc.finish_time && frm.doc.operation_time) {
        var finish_time = parseTime(frm.doc.finish_time);
        var operation_time = parseTime(frm.doc.operation_time);

        var time_difference_in_minutes = (finish_time - operation_time) / (1000 * 60);
        // ถ้าวันที่ต่างกัน ให้เพิ่มนาทีของวัน (1440 นาทีต่อวัน)
        if (days_difference > 0) {
            time_difference_in_minutes += days_difference * 1440;
        }
        frm.set_value('time_used', Math.abs(Math.round(time_difference_in_minutes)) || 0); 
    } else {
        frm.set_value('time_used', 0);
    }
}

function parseTime(timeStr) {
    var parts = timeStr.split(':');
    var date = new Date();
    date.setHours(parseInt(parts[0], 10));
    date.setMinutes(parseInt(parts[1], 10));
    date.setSeconds(parseInt(parts[2], 10));
    return date;
}


