function update_list_name(frm, cdt, cdn) {
    var row = locals[cdt][cdn];
    var signs = [];
    var fields = ['sign1', 'sign2', 'sign3'];

    Promise.all(fields.map(field => {
        if (row[field]) {
            return frappe.db.get_value('Personnel', row[field], 'fullname')
                .then(r => {
                    if (r && r.message && r.message.fullname) {
