frappe.ui.form.on('Parcel Stock', {
    after_workflow_action: function(frm) {
        // ตรวจสอบว่า wf_pcs_state เป็น "รับเข้าแล้ว" หรือ "อนุมัติเบิกของ"
        if (frm.doc.wf_pcs_state === "รับเข้าแล้ว" || frm.doc.wf_pcs_state === "อนุมัติเบิกของ") {

            // ตรวจสอบว่า type เป็น "รับเข้า"
            if (frm.doc.type === "รับเข้า") {
                frm.doc.parcel_stock_table.forEach(function(row) {

                    frappe.db.get_value('Parcel Product', { 'name': row.product_code }, ['qty_remaining_stock'], (r) => {
                        if (r) {
                            let updated_qty_remaining_stock = (r.qty_remaining_stock || 0) + row.qty_real;

                            frappe.db.set_value('Parcel Product', row.product_code, {
                                'qty_remaining_stock': updated_qty_remaining_stock
                            }).then(response => {
                                frappe.msgprint({
                                    message: '<span style="color: green;">' + __('รับเข้ารายการ: ' + row.product_list + ' จำนวน: ' + row.qty_real) + '</span>',
                                    indicator: 'green'
                                });
                            });
                        }
                    });
                });
            }

            // เมื่อ type เป็น "เบิก/ใช้ไป" ทำการตัดสต็อก
            else if (frm.doc.type === "เบิก/ใช้ไป") {
                frm.doc.parcel_stock_table.forEach(function(row) {
                    // ตรวจสอบว่า stock_card_type เป็น "ใบขอซื้อ" หรือไม่
                    if (row.stock_card_type === "ใบขอซื้อ") {
                        return; // ถ้าเป็น "ใบขอซื้อ" ไม่ต้องตัดสต็อก
                    }

                    // ดึงค่าของ product_id จาก Doctype Product
                    frappe.db.get_value('Parcel Product', { 'name': row.product_code }, ['qty_remaining_stock', 'qty_waiting_withdraw'], (r) => {
                        if (r) {
                            // ตรวจสอบว่าจำนวนสต็อกเพียงพอหรือไม่
                            if ((r.qty_remaining_stock || 0 || r.qty_waiting_withdraw) >= row.qty_real) {
                                // ตัดจำนวนที่เบิกออกจาก qty_remaining_stock
                                let updated_qty_remaining_stock = (r.qty_remaining_stock || 0) - row.qty_real;
                                let updated_qty_waiting_withdraw = (r.qty_waiting_withdraw || 0) - row.qty_real;

                                // อัปเดตค่าของฟิลด์ qty_remaining_stock ใน Doctype Product
                                frappe.db.set_value('Parcel Product', row.product_code, {
                                    'qty_remaining_stock': updated_qty_remaining_stock,
                                    'qty_waiting_withdraw': updated_qty_waiting_withdraw
                                }).then(response => {
                                        frappe.msgprint({
                                            message: '<span style="color: green;">' + __('ตัดสต็อกสำเร็จสำหรับรายการ: ' + row.product_list + ' จำนวน: ' + row.qty_real) + '</span>',
                                            indicator: 'green'
                                        });
                                });
                            } 
                        }
                    });
                });
            }
        }

        // ตรวจสอบว่า wf_pcs_state เป็น "ยกเลิก"
        else if (frm.doc.wf_pcs_state === "ยกเลิก") {
            // กรณี type เป็น "รับเข้า" ให้ลดจำนวนสต็อกออก
            if (frm.doc.type === "รับเข้า") {
                frm.doc.parcel_stock_table.forEach(function(row) {
                    frappe.db.get_value('Parcel Product', { 'name': row.product_code }, ['qty_remaining_stock', 'qty_withdrawn_stock'], (r) => {
                        if (r) {
                            // คำนวณจำนวนสต็อกที่เหลือหลังจากลด
                            let updated_qty_remaining = (r.qty_remaining_stock || 0) - row.qty_real;
                            let updated_qty_withdrawn = (r.qty_withdrawn_stock || 0) - row.qty_real;

                            // ตรวจสอบไม่ให้ qty_remaining_stock ติดลบ ถ้าติดลบ ให้ตั้งค่าเป็น 0
                            updated_qty_withdrawn = updated_qty_withdrawn < 0 ? 0 : updated_qty_withdrawn;

                            // อัปเดตค่า qty_remaining_stock ในฐานข้อมูล
                            frappe.db.set_value('Parcel Product', row.product_code, {
                              'qty_remaining_stock': updated_qty_remaining,
                              'qty_withdrawn_stock': updated_qty_withdrawn
                            }).then(response => {
                                    frappe.msgprint({
                                        message: '<span style="color: Orange;">' + __('ยกเลิกรายการ: ' + row.product_list + ' จำนวน: ' + row.qty_real + ' ถูกลบออกจากสต็อก') + '</span>',
                                        indicator: 'Orange'
                                    });
                                });
                        }
                    });
                });
            }

            // กรณี type เป็น "เบิก/ใช้ไป" ให้คืนจำนวนสต็อกกลับ
            else if (frm.doc.type === "เบิก/ใช้ไป") {
                frm.doc.parcel_stock_table.forEach(function(row) {
                    // ตรวจสอบว่า stock_card_type เป็น "ใบขอซื้อ" หรือไม่
                    if (row.stock_card_type === "ใบขอซื้อ") {
                        return; // ถ้าเป็น "ใบขอซื้อ" ไม่ต้องคืนสต็อก
                    }

                    frappe.db.get_value('Parcel Product', { 'name': row.product_code }, ['qty_remaining_stock', 'qty_withdrawn_stock'], (r) => {
                        if (r) {
                            // คืนจำนวนสต็อกที่ถูกตัดไปก่อนหน้านี้
                            let updated_qty_remaining = (r.qty_remaining_stock || 0) + row.qty_real;
                            let updated_qty_withdrawn = (r.qty_withdrawn_stock || 0) + row.qty_real;

                            // ตรวจสอบไม่ให้ qty_withdrawn_stock ติดลบ
                            updated_qty_withdrawn = updated_qty_withdrawn < 0 ? 0 : updated_qty_withdrawn;

                            // อัปเดตฟิลด์ qty_remaining_stock และ qty_withdrawn_stock ใน Doctype Parcel Product
                            frappe.db.set_value('Parcel Product', row.product_code, {
                                'qty_remaining_stock': updated_qty_remaining,
                                'qty_withdrawn_stock': updated_qty_withdrawn
                            }).then(response => {
                                frappe.msgprint({
                                    message: '<span style="color: Orange;">' + __('ยกเลิกรายการ: ' + row.product_list + ' จำนวน: ' + row.qty_real + ' ถูกคืนกลับสต็อก') + '</span>',
                                    indicator: 'Orange'
                                });
                            });
                        }
                    });
                });
            }
        }

        else if (frm.doc.wf_pcs_state === "ไม่อนุมัติ") {
            // กรณี type เป็น "เบิก/ใช้ไป" ให้คืนจำนวนสต็อกกลับ
            if (frm.doc.type === "เบิก/ใช้ไป") {
                frm.doc.parcel_stock_table.forEach(function(row) {
                    // ตรวจสอบว่า stock_card_type เป็น "ใบขอซื้อ" หรือไม่
                    if (row.stock_card_type === "ใบขอซื้อ") {
                        return; // ถ้าเป็น "ใบขอซื้อ" ไม่ต้องคืนสต็อก
                    }

                    frappe.db.get_value('Parcel Product', { 'name': row.product_code }, ['qty_remaining_stock', 'qty_withdrawn_stock', 'qty_waiting_withdraw'], (r) => {
                        if (r) {
                            // ลบจำนวนที่กำลังรอเบิกจากฟิลด์ qty_waiting_withdraw
                            let updated_qty_waiting_withdraw = (r.qty_waiting_withdraw || 0) - row.qty_real;
                            updated_qty_waiting_withdraw = updated_qty_waiting_withdraw < 0 ? 0 : updated_qty_waiting_withdraw;

                            // คืนจำนวนสต็อกที่ถูกตัดไปก่อนหน้านี้
                            let updated_qty_remaining = (r.qty_remaining_stock || 0);
                            let updated_qty_withdrawn = (r.qty_withdrawn_stock || 0) + row.qty_real;

                            // ตรวจสอบไม่ให้ qty_withdrawn_stock ติดลบ
                            updated_qty_withdrawn = updated_qty_withdrawn < 0 ? 0 : updated_qty_withdrawn;

                            // อัปเดตฟิลด์ qty_waiting_withdraw, qty_remaining_stock และ qty_withdrawn_stock ใน Doctype Parcel Product
                            frappe.db.set_value('Parcel Product', row.product_code, {
                                'qty_waiting_withdraw': updated_qty_waiting_withdraw,
                                'qty_remaining_stock': updated_qty_remaining,
                                'qty_withdrawn_stock': updated_qty_withdrawn
                            }).then(response => {
                                frappe.msgprint({
                                    message: '<span style="color: Orange;">' + __('ยกเลิกรายการ: ' + row.product_list + ' จำนวน: ' + row.qty_real + ' ถูกคืนกลับสต็อก') + '</span>',
                                    indicator: 'Orange'
                                });
                            });
                        }
                    });
                });
            }
        }        
    }
});


frappe.ui.form.on('Parcel Stock', {
    validate: async function(frm) {
        if (frm.doc.wf_pcs_state === "อนุมัติเบิกของ" || frm.doc.wf_pcs_state === "จัดของเรียบร้อยแล้ว") {
            return;
        }

        if (frm.doc.type == "เบิก/ใช้ไป") {
            let can_save = true;

            for (let row of frm.doc.parcel_stock_table) {
                // ตรวจสอบว่า stock_card_type เป็น "ใบขอซื้อ" หรือไม่
                if (row.stock_card_type === "ใบขอซื้อ") {
                    continue; // ข้ามการตัด Stock ถ้าเป็น "ใบขอซื้อ"
                }

                let r = await frappe.db.get_value('Parcel Product', { 'name': row.product_code }, ['qty_remaining_stock', 'qty_waiting_withdraw']);

                if (r) {
                    let qty_remaining_stock = r.message.qty_remaining_stock || 0;
                    let qty_waiting_withdraw = r.message.qty_waiting_withdraw || 0;
                    let display_qty_withdrawn_stock = qty_remaining_stock - qty_waiting_withdraw;
                    let display_qty = row.qty_real - display_qty_withdrawn_stock;

                    // ตรวจสอบจำนวนว่ามีเพียงพอใน stock หรือไม่
                    if (row.qty_real > display_qty_withdrawn_stock) {
                        frappe.msgprint({
                            message: '<span style="color: red;">' + __('ไม่สามารถเบิกของจำนวนนี้ได้ เนื่องจากของไม่พอใน Stock สำหรับรายการ: ' + row.product_code + ' ' + row.product_list + '<br>จำนวนคงเหลือ: ' + display_qty_withdrawn_stock + ' ' + row.unit + '<br>กรุณาเบิกของตามที่คงเหลือใน Stock') + '</span>',
                            indicator: 'red'
                        });

                        can_save = false;
                        frappe.validated = false;
                    } else if (frm.doc.wf_pcs_state === "รออนุมัติ") {
                        // ตรวจสอบว่ามีค่า qty_waiting_withdraw เดิมที่บันทึกไว้ใน row หรือไม่
                        let previous_qty_waiting_withdraw = row.previous_qty_waiting_withdraw || 0;

                        // หากมีการแก้ไข qty_real จะต้องเก็บค่าเดิมไว้ใน previous_qty_waiting_withdraw
                        if (row.qty_real !== previous_qty_waiting_withdraw) {
                            // อัปเดต previous_qty_waiting_withdraw เป็นค่าเดิมก่อนที่จะเปลี่ยนค่า qty_real
                            row.previous_qty_waiting_withdraw = previous_qty_waiting_withdraw;
                        }

                        // หักค่าจำนวนเดิมออกจากสต็อกก่อน แล้วบวกจำนวนใหม่เข้าไป
                        let updated_qty_waiting = qty_waiting_withdraw - previous_qty_waiting_withdraw + row.qty_real;

                        console.log(`Row ID: ${row.name}, previous_qty_waiting_withdraw:`, previous_qty_waiting_withdraw);
                        console.log(`Row ID: ${row.name}, updated_qty_waiting:`, updated_qty_waiting);

                        // ตรวจสอบการใช้ `product_code` เป็นตัวระบุ หรือ ดึงจากชื่อ `name` ของ Parcel Product
                        await frappe.db.set_value('Parcel Product', row.product_code, {
                            'qty_waiting_withdraw': updated_qty_waiting,
                            'qty_withdrawn_stock': qty_remaining_stock - updated_qty_waiting
                        });

                        // บันทึกค่าใหม่ใน row สำหรับการตรวจสอบการเปลี่ยนแปลงในอนาคต
                        row.previous_qty_waiting_withdraw = row.qty_real; // เก็บค่า qty ใหม่ไว้ใน previous_qty_waiting_withdraw
                    }
                }
            }

            if (!can_save) {
                frappe.validated = false;
            }
        }
    }
});



