frappe.ui.form.on('Parcel Stock', {
    fullname: function(frm) {
        if (frm.doc.fullname) {
            // ดึงข้อมูลบุคคลจาก fullname
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Personnel',
                    filters: { 'fullname': frm.doc.fullname },
                    fieldname: ['sig', 'department']
                },
                callback: function(response) {
                    if (response.message) {
                        const personnel_department = response.message.department;

                        if (personnel_department === 'จัดซื้อและพัสดุ') {
                            // หากแผนกคือ "จัดซื้อและพัสดุ" ให้แสดงลายเซ็นของ fullname
                            frm.set_value('sig', response.message.sig);
                        } else {
                            // หากไม่ใช่แผนก "จัดซื้อและพัสดุ" ให้ดึงลายเซ็นของ "ปริชญา มณีโชติ"
                            frappe.call({
                                method: 'frappe.client.get_value',
                                args: {
                                    doctype: 'Personnel',
                                    filters: { 'fullname': 'ปริชญา มณีโชติ' },
                                    fieldname: ['sig']
                                },
                                callback: function(pricha_response) {
                                    if (pricha_response.message) {
                                        frm.set_value('sig', pricha_response.message.sig);
                                    } else {
                                        frm.set_value('sig', null);
                                        frappe.msgprint(__('ไม่พบลายเซ็นสำหรับ "ปริชญา มณีโชติ"'));
                                    }
                                }
                            });
                        }
                    } else {
                        frm.set_value('sig', null);
                        frappe.msgprint(__('ไม่พบข้อมูลบุคคลนี้ในระบบ'));
                    }
                }
            });
