    qty: function(frm, cdt, cdn) {
        if (frm.doc.type === "รับเข้า") { // เช็ค type ก่อนคำนวณ
            calculate_total(frm, cdt, cdn); // คำนวณเมื่อเปลี่ยนแปลง qty
        }
    }
});

// ฟังก์ชันคำนวณค่า total
function calculate_total(frm, cdt, cdn) {
    let row = locals[cdt][cdn]; // ดึงข้อมูล row ปัจจุบันใน Child Table
    row.total = (row.price || 0) * (row.qty || 0); // คำนวณ total
    frm.refresh_field('parcel_stock_table'); // รีเฟรชตาราง
}


