        }
    },
    validate: function (frm) {
        if (!check_posting_date(frm, true)) {
            frappe.validated = false;
        }
    }
});

function check_posting_date(frm, is_save) {
    let posting_date = frm.doc.posting_date;
    let is_special = frm.doc.special;
    let type = frm.doc.type; // ดึงค่าประเภทของเอกสาร

    // ตรวจสอบว่า type เป็น "เบิก/ใช้ไป" หรือไม่
    if (type !== "เบิก/ใช้ไป") {
        return true; // ถ้าไม่ใช่ประเภทนี้ ให้ข้ามการตรวจสอบ
    }

    if (posting_date) {
        if (is_special) {
            if (!is_save && !frm._posting_date_checked) {
                frm._posting_date_checked = true;
            }
            return true;
        }

        let now = new Date();
        let date = new Date(posting_date);
        let day = date.getDay();
        let current_hour = now.getHours();
        let current_minutes = now.getMinutes();
        let current_time_in_minutes = current_hour * 60 + current_minutes;

        const WED_START = 12 * 60;
        const WED_END = 17 * 60;
        const THU_START = 8 * 60;
        const THU_END = 10 * 60 + 30;

        if ((day === 3 && current_time_in_minutes >= WED_START && current_time_in_minutes <= WED_END) ||
            (day === 4 && current_time_in_minutes >= THU_START && current_time_in_minutes <= THU_END)) {
            if (!is_save && !frm._posting_date_checked) {
                frm._posting_date_checked = true;
            }
            return true;
        } else {
            if (is_save || !frm._posting_date_checked) {
                frappe.msgprint({
                    message: '<span style="color: red;">' + __('ไม่อยู่ในช่วงเบิกของ สามารถดำเนินการได้ตามรายละเอียดดังนี้' +
                        '<br>1. ทุกวันพุธ เวลา 12.00 - 17.00 น.' +
                        '<br>2. ทุกวันพฤหัสบดี เวลา 08.00 - 10.30 น.' +
                        '<br>กรุณาติดต่อแผนกจัดซื้อและพัสดุ หากต้องการเบิกของนอกเหนือจากวันที่กำหนด') + '</span>',
                    indicator: 'red'
                });
                frm._posting_date_checked = true;
            }
            return false;
        }
    } else {
        frappe.msgprint({
            message: '<span style="color: red;">' + __('กรุณาระบุวันที่ก่อนดำเนินการ') + '</span>',
            indicator: 'red'
        });

        return false;
    }
}


