function toggleHtmlDisplay(frm) {
    const now = new Date();
    const today = now.getDay(); // วันในสัปดาห์ (0 = อาทิตย์, 1 = จันทร์, ..., 6 = เสาร์)
    const hours = now.getHours(); // ชั่วโมง (0-23)
    const minutes = now.getMinutes(); // นาที (0-59)

    // เงื่อนไขสำหรับวันพุธ (12:00 - 17:00)
    const isWednesdayRestricted = (today === 3 && (hours >= 12 && hours < 17));

    // เงื่อนไขสำหรับวันพฤหัสบดี (08:00 - 10:30)
    const isThursdayRestricted = (today === 4 && 
        ((hours === 8) || (hours === 9) || (hours === 10 && minutes <= 30)));

    // ตรวจสอบค่าในฟิลด์ type
    const isReceiveType = (frm.doc.type === "รับเข้า");
    const isWithdrawType = (frm.doc.type === "เบิก/ใช้ไป");
    const isEmptyType = (!frm.doc.type || frm.doc.type.trim() === ""); // ตรวจสอบว่า type ว่างหรือไม่

    // ซ่อนหรือแสดงฟิลด์ html_display ตามเงื่อนไข
    if (isEmptyType || isReceiveType) {
        // ถ้า type ว่างหรือ type = "รับเข้า": ซ่อนฟิลด์
        frm.toggle_display('html_display', false);
    } else if (isWithdrawType) {
        // ถ้า type = "เบิก/ใช้ไป": ตรวจสอบเงื่อนไขวันเวลา
        if (!isWednesdayRestricted && !isThursdayRestricted) {
            frm.toggle_display('html_display', true); // แสดงฟิลด์

        } else {
            frm.toggle_display('html_display', false); // ซ่อนฟิลด์
        }
    } else {
        // กรณีอื่น ๆ: ซ่อนฟิลด์
        frm.toggle_display('html_display', false);
    }
}

frappe.ui.form.on('Parcel Stock', {
    refresh: function(frm) {
        // ตรวจสอบว่าเอกสารเป็นแบบใหม่ (ยังไม่บันทึก) หรือไม่
        if (frm.doc.__islocal) {
            // ตรวจสอบว่า type เป็น "เบิก/ใช้ไป" หรือไม่
            if (frm.doc.type === "เบิก/ใช้ไป") {
                // ตรวจสอบเงื่อนไขเวลาและวันที่
                const now = new Date();
                const dayOfWeek = now.getDay(); // 0=Sunday, 1=Monday, ..., 6=Saturday
                const hours = now.getHours();
                const minutes = now.getMinutes();

                // เงื่อนไขเวลาและวันที่
                const isWednesday = dayOfWeek === 3; // วันพุธ
                const isThursday = dayOfWeek === 4; // วันพฤหัสบดี
                const isWednesdayTime = isWednesday && (hours >= 12 && hours < 17);
                const isThursdayTime = isThursday && ((hours === 8 && minutes >= 0) || (hours > 8 && hours < 10) || (hours === 10 && minutes <= 30));

                // ตรวจสอบว่าไม่อยู่ในช่วงเวลาที่กำหนด
                if (!isWednesdayTime && !isThursdayTime) {
                    // หากไม่อยู่ในช่วงเวลาที่กำหนด ให้ซ่อนช่อง parcel_stock_table
                    frm.toggle_display('parcel_stock_table', false); // หรือใช้ frm.set_df_property
                } else {
                    // หากอยู่ในช่วงเวลาที่กำหนด ให้แสดงช่อง parcel_stock_table
                    frm.toggle_display('parcel_stock_table', true); // หรือใช้ frm.set_df_property
                }
            } else {
                // หาก type ไม่ใช่ "เบิก/ใช้ไป" ให้แสดงช่อง parcel_stock_table
                frm.toggle_display('parcel_stock_table', true); // หรือใช้ frm.set_df_property
            }
        } else {
            // หากเอกสารถูกบันทึกแล้ว ให้แสดงช่อง parcel_stock_table
            frm.toggle_display('parcel_stock_table', true); // หรือใช้ frm.set_df_property
        }
    }
});

