function check_posting_date(frm, is_save) {
    let posting_date = frm.doc.posting_date;
    let is_special = frm.doc.special; 
    let is_pr = frm.doc.is_pr; // ดึงค่าของ is_pr

    // ✅ ถ้า is_pr เป็น "มีบริษัท" → ให้ผ่านการตรวจสอบได้เลย
    if (is_pr === "มีบริษัท") {
        return true;
    }

    if (posting_date) {
        if (is_special) {
            if (!is_save && !frm._posting_date_checked) {
                frm._posting_date_checked = true;
            }
            return true;
        }

        let now = new Date();
        let date = new Date(posting_date);
        let day = date.getDay();
        let current_hour = now.getHours();
        let current_minutes = now.getMinutes();
        let current_time_in_minutes = current_hour * 60 + current_minutes;

        const SUNDAY_START = 8 * 60;
        const SUNDAY_END = 16 * 60;
        const MONDAY_START = 8 * 60;
        const MONDAY_END = 12 * 60;

        if ((day === 0 && current_time_in_minutes >= SUNDAY_START && current_time_in_minutes <= SUNDAY_END) ||
            (day === 1 && current_time_in_minutes >= MONDAY_START && current_time_in_minutes <= MONDAY_END)) {
            if (!is_save && !frm._posting_date_checked) {
                frm._posting_date_checked = true;
            }
            return true;
        } else {
            if (is_save || !frm._posting_date_checked) {
                frappe.msgprint({
                    message: '<span style="color: red;">' + __('ไม่อยู่ในช่วงเปิดใบขอซื้อ สามารถดำเนินการได้ตามรายละเอียดดังนี้' +
                        '<br>1. ทุกวันอาทิตย์ เวลา 08.00 - 16.00 น.' +
                        '<br>2. ทุกวันจันทร์ เวลา 08.00 - 12.00 น.' +
                        '<br>กรุณาติดต่อแผนกจัดซื้อและพัสดุ หากต้องการเปิดใบขอซื้อนอกเหนือจากวันที่กำหนด') + '</span>',
                    indicator: 'red'
                });
                frm._posting_date_checked = true;
            }
            return false;
        }
    } else {
        frappe.msgprint({
            message: '<span style="color: red;">' + __('กรุณาระบุวันที่ก่อนดำเนินการ') + '</span>',
            indicator: 'red'
        });

        return false;
    }
}


