function toggleHtmlDisplay(frm) {
    const now = new Date();
    const today = now.getDay(); // วันในสัปดาห์ (0 = อาทิตย์, 1 = จันทร์, ..., 6 = เสาร์)
    const hours = now.getHours(); // ชั่วโมง (0-23)
    const minutes = now.getMinutes(); // นาที (0-59)

    // เงื่อนไขสำหรับวันอาทิตย์ (08:00 - 16:00)
    const isSundayRestricted = (today === 0 && (hours >= 8 && hours < 16));

    // เงื่อนไขสำหรับวันจันทร์ (08:00 - 12:00)
    const isMondayRestricted = (today === 1 && (hours >= 8 && hours < 12));

    // ตรวจสอบเงื่อนไขเวลาและวันที่
    if (!isSundayRestricted && !isMondayRestricted) {
        frm.toggle_display('html_display', true);
    } else {
        frm.toggle_display('html_display', false);
    }
}

