function verifyPeopleID(PID) {
    // ตรวจสอบว่าทุก ๆ ตัวอักษรเป็นตัวเลข
    if (!/^\d+$/.test(PID)) {
        return false;
    }
    // ตรวจสอบว่าข้อมูลมีทั้งหมด 13 ตัวอักษร
    if (PID.trim().length !== 13) {
        return false;
    }
    var sumValue = 0;
    // คำนวณค่า checksum
    for (var i = 0; i < PID.length - 1; i++) {
        sumValue += parseInt(PID[i]) * (13 - i);
    }
    var v = (11 - (sumValue % 11)) % 10;
    // ตรวจสอบว่าหมายเลขสุดท้ายตรงกับค่า checksum ที่คำนวณได้
    return PID[12] == v.toString();
}


