frappe.ui.form.on('Patient Register Khian Sa', {
    before_save: function(frm) {
        // Retrieve the values from the form fields
        var house_no = frm.doc.house_no || "";
        var moo = frm.doc.moo ? 'ม.' + frm.doc.moo : "";
        var road = frm.doc.road ? 'ถ.' + frm.doc.road : "";
        var soi = frm.doc.soi ? 'ซ.' + frm.doc.soi : "";
        var tambon = frm.doc.tambon || "";
        var amphoe = frm.doc.amphoe || "";
        var province = frm.doc.province || "";
        var postal_code = frm.doc.postal_code || "";

        // Construct the address string
        var address = house_no + " " + moo;
        if (soi || road) {
            address += " " + road + " " + soi;
        }

        // Append address components based on the availability of values
        if (province === 'กรุงเทพมหานคร') {
            address += " " + tambon;
            if (amphoe) {
                address += ' เขต' + amphoe;
            }
            address += " " + province + " " + postal_code;
        } else {
            if (tambon) {
                address += ' ต.' + tambon;
            }
            if (amphoe) {
                address += ' อ.' + amphoe;
            }
            if (province) {
                address += ' จ.' + province;
            }
            address += " " + postal_code;
        }

        // Update the address field
        frm.set_value('address', address.trim());
    }
});


frappe.ui.form.on('Patient Register Khian Sa', {
    validate: function(frm) {
        // รับค่าวันเกิด
        var bithdate = frm.doc.bithdate;
        
        if (bithdate) {
            // แปลงวันเกิดเป็นวัตถุของ JavaScript Date
            var bithdate = new Date(bithdate);

            // ดึงข้อมูลวันที่ปัจจุบัน
            var currentDate = new Date();

            // คำนวณอายุในปี
            var years = currentDate.getFullYear() - bithdate.getFullYear();
            var months = currentDate.getMonth() - bithdate.getMonth();
            var days = currentDate.getDate() - bithdate.getDate();
            
            if (days < 0) {
                months--;
                days += new Date(currentDate.getFullYear(), currentDate.getMonth(), 0).getDate();
            }
            
            if (months < 0) {
                years--;
                months += 12;
            }

            // อัพเดทอายุใน form
            frm.set_value('age', years);
            frm.set_value('month', months);
            frm.set_value('day', days);
        } else {
            // ถ้าไม่มีข้อมูลวันเกิด, ตั้งค่า fields 'age_years', 'age_months', 'age_days' เป็นช่องว่าง
            frm.set_value('age', "");
            frm.set_value('month', "");
            frm.set_value('day', "");
        }
    }
});

frappe.ui.form.on('Patient Register Khian Sa', {
    before_save: function(frm) {
        if (!frm.doc.hn) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Patient Register Khian Sa",
                    fields: ["hn"],
                    limit_page_length: 1,
                    order_by: "creation desc"
                },
                callback: function(response) {
                    let starting_hn = 00003496; // เริ่มที่ 2407
                    let new_hn;

                    if (response.message.length > 0) {
                        let last_hn = response.message[0].hn;
                        if (last_hn && !isNaN(parseInt(last_hn, 10))) {
                            new_hn = Math.max(parseInt(last_hn, 10) + 1, starting_hn).toString().padStart(8, '0');
                        } else {
                            new_hn = starting_hn.toString().padStart(8, '0');
                        }
                    } else {
                        new_hn = starting_hn.toString().padStart(8, '0');
                    }

                    // ตรวจสอบว่า HN ซ้ำหรือไม่
                    frappe.call({
                        method: "frappe.client.get_list",
                        args: {
                            doctype: "Patient Register Khian Sa",
                            filters: { hn: new_hn },
                            fields: ["name"]
                        },
                        callback: function(check_response) {
                            if (check_response.message.length > 0) {
                                frappe.throw(__('HN {0} already exists. Please try again.', [new_hn]));
                            } else {
                                frm.set_value('hn', new_hn); // ตั้งค่า HN ที่ไม่ซ้ำ
                            }
                        }
                    });
                }
            });
        }
    }
});



frappe.ui.form.on('Patient Register Khian Sa', {
    refresh: function(frm) {
        // สร้างปุ่ม "ออก Visit"
        frm.add_custom_button(__('ออก Visit'), function() {
            // ตรวจสอบว่า HN มี visit ในวันนี้แล้วหรือไม่
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Visit Khian Sa",
                    fields: ["name", "creation"],
                    filters: {
                        hn: frm.doc.hn,
                        creation: [">=", frappe.datetime.now_date()]
                    },
                    limit_page_length: 1
                },
                callback: function(checkVisitResponse) {
                    if (checkVisitResponse.message.length > 0) {
                        // มี visit ที่ถูกสร้างในวันนี้แล้ว
                        frappe.msgprint({
                            message: '<span style="color: red">' + __('HN นี้ได้ทำการออก Visit ในวันนี้แล้ว ไม่สามารถออกซ้ำได้') + '</span>',
                            indicator: 'red'
                        });
                    } else {
                        // ดึงหมายเลข visit ล่าสุดก่อนสร้างเอกสารใหม่
                        frappe.call({
                            method: "frappe.client.get_list",
                            args: {
                                doctype: "Visit Khian Sa",
                                fields: ["visit"],
                                limit_page_length: 1,
                                order_by: "creation desc"
                            },
                            callback: function(getListResponse) {
                                let new_visit_number = '00000001';  // ค่าเริ่มต้นหากไม่มีหมายเลขก่อนหน้า
                                if (getListResponse.message.length > 0) {
                                    let last_visit = getListResponse.message[0].visit;
                                    if (last_visit && !isNaN(parseInt(last_visit, 10))) {
                                        // เพิ่มหมายเลข visit ใหม่โดยบวก 1 และเติม 0 ให้ครบ 8 หลัก
                                        new_visit_number = (parseInt(last_visit, 10) + 1).toString().padStart(8, '0');
                                    }
                                }

                                // สร้างเอกสารใหม่ใน DocType: Visit Khian Sa
                                frappe.call({
                                    method: 'frappe.client.insert',
                                    args: {
                                        doc: {
                                            doctype: 'Visit Khian Sa',
                                            fullname: frm.doc.fullname,  // ดึงข้อมูลจากฟิลด์ fullname ของ Patient Register Khian Sa
                                            visit: new_visit_number,      // กำหนดหมายเลข visit ใหม่
                                            hn: frm.doc.hn
                                        }
                                    },
                                    callback: function(response) {
                                        if (response.message) {
                                            frappe.msgprint({
                                                message: '<span style="color: green">' + __('ออก Visit : ' + new_visit_number + ' เรียบร้อย') + '</span>',
                                                indicator: 'green'
                                            });

                                            // รีเฟรชหรือทำการ redirect ถ้าต้องการไปหน้า Visit
                                            window.open('http://sehsmart.surateyehospital.com:8280/app/visit-khian-sa/' + response.message.name, '_blank');
                                        }
                                    }
                                });
                            }
                        });
                    }
                }
            });
        });
    }
});

