frappe.ui.form.on('Visit Khian Sa', {
    refresh: function(frm) {
        if (!frm.fields_dict.copy_name) return;

        frm.fields_dict.copy_name.$input.on('click', function() {
            if (frm.doc.fullname) {
                // ตรวจสอบว่า clipboard API รองรับหรือไม่
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(frm.doc.fullname).then(() => {
                        // frappe.msgprint({
                        //     title: __('Success'),
                        //     message: __('The fullname has been copied to your clipboard.'),
                        //     indicator: 'green'
                        // });
                    }).catch(err => {
                        // frappe.msgprint({
                        //     title: __('Error'),
                        //     message: __('Could not copy the fullname. Please try again.'),
                        //     indicator: 'red'
                        // });
                        console.error('Clipboard copy failed:', err);
                    });
                } else {
                    // สำรอง: ใช้วิธีสร้าง textarea ชั่วคราว
                    const textarea = document.createElement('textarea');
                    textarea.value = frm.doc.fullname;
                    document.body.appendChild(textarea);
                    textarea.select();
                    try {
                        document.execCommand('copy');
                        // frappe.msgprint({
                        //     title: __('Success'),
                        //     message: __('The fullname has been copied to your clipboard.'),
                        //     indicator: 'green'
                        // });
                    } catch (err) {
                        // frappe.msgprint({
                        //     title: __('Error'),
                        //     message: __('Could not copy the fullname. Please try again.'),
                        //     indicator: 'red'
                        // });
                        console.error('Fallback copy failed:', err);
                    } finally {
                        document.body.removeChild(textarea);
                    }
                }
            } else {
                // frappe.msgprint({
                //     title: __('Warning'),
                //     message: __('The fullname field is empty.'),
                //     indicator: 'orange'
                // });
            }
        });
    }
});

frappe.ui.form.on('Doctor Room Khian Sa', {
    before_save: function(frm) {
        // ตรวจสอบว่า User ที่ล็อกอินมี role_profile_name เป็น "Doctor"
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'User',
                fields: ['full_name', 'bio'],
                filters: {
                    'name': frappe.session.user,
                    'role_profile_name': 'Doctor'
                },
                limit_page_length: 1
            },
            callback: function(response) {
                if (response.message && response.message.length > 0) {
                    // ตั้งค่าชื่อ full_name ไปที่ช่อง doctor_name
                    frm.set_value('doctor_name', response.message[0].full_name);
                    frm.set_value('vol', response.message[0].bio);
                    
                    // ตั้งค่าวันปัจจุบันลงในช่อง date_test_results
                    frm.set_value('date_test_results', frappe.datetime.nowdate());
                }
            }
        });
    }
});

frappe.ui.form.on('Doctor Room Khian Sa', {
    // Trigger when the field 'disease_re' or 'disease_le' is changed
    disease_re: function(frm) {
        update_status(frm);
    },
    disease_le: function(frm) {
        update_status(frm);
    }
});

function update_status(frm) {
    if (frm.doc.disease_re === "No DR ไม่มีเบาหวานขึ้นตา" && frm.doc.disease_le === "No DR ไม่มีเบาหวานขึ้นตา") {
        frm.set_value('summary_results', 'ปกติ');
    } else {
        frm.set_value('summary_results', 'ผิดปกติ');
    }
}

