frappe.ui.form.on('Myopia Clinic', {
    validate: function(frm) {
        // รับค่าวันเกิด
        var birthday = frm.doc.birthday;
        
        if (birthday) {
            // แปลงวันเกิดเป็นวัตถุของ JavaScript Date
            var birthday = new Date(birthday);

            // ดึงข้อมูลวันที่ปัจจุบัน
            var currentDate = new Date();

            // คำนวณอายุในปี
            var years = currentDate.getFullYear() - birthday.getFullYear();
            var months = currentDate.getMonth() - birthday.getMonth();
            var days = currentDate.getDate() - birthday.getDate();
            
            if (days < 0) {
                months--;
                days += new Date(currentDate.getFullYear(), currentDate.getMonth(), 0).getDate();
            }
            
            if (months < 0) {
                years--;
                months += 12;
            }

            // อัพเดทอายุใน form
            frm.set_value('age', years);
            // คำนวณค่า AL/CR
            if (cur_frm.doc.axial_length && cur_frm.doc.average_k) {
                var al_cr = cur_frm.doc.axial_length / cur_frm.doc.average_k;
                // ปัดค่า AL/CR ให้เหลือ 2 ตำแหน่ง
                al_cr = parseFloat(al_cr.toFixed(2)); // หรือใช้ Math.round(al_cr * 100) / 100
                cur_frm.set_value("al_cr", al_cr);
            } 

            if (cur_frm.doc.axial_length1 && cur_frm.doc.average_k1) {
                var al_cr1 = cur_frm.doc.axial_length1 / cur_frm.doc.average_k1;
                // ปัดค่า AL/CR ให้เหลือ 2 ตำแหน่ง
                al_cr1 = parseFloat(al_cr1.toFixed(2)); // หรือใช้ Math.round(al_cr * 100) / 100
                cur_frm.set_value("al_cr1", al_cr1);
            } 

            // ตรวจสอบเงื่อนไขหากอายุเกิน 18 ปี
            if (years > 18) {
                frappe.msgprint({
                    message: '<span style="color: red">' + __('คนไข้รายนี้มีอายุเกิน 18 ปี') + '</span>',
                    indicator: 'red'
                });
                frappe.validated = false; // ป้องกันการบันทึก
            }
            
        } else {
            // ถ้าไม่มีข้อมูลวันเกิด, ตั้งค่า fields 'age' เป็นช่องว่าง
            frm.set_value('age', "");
        }
    }
});

