            return 0; // คืนค่า 0 หากไม่อยู่ในช่วง
        }

        if (percentile_al_cr_map[age] && percentile_al_cr_map[age][gender]) {
            const ranges = percentile_al_cr_map[age][gender];

            // คำนวณ percentile สำหรับ al_cr
            const percentile_al_cr = calculate_percentile_al_cr(al_cr, ranges);
            frm.set_value('percentile_al_cr', percentile_al_cr || 0);

            // คำนวณ percentile สำหรับ al_cr
            const percentile_al_cr1 = calculate_percentile_al_cr(al_cr1, ranges);
            frm.set_value('percentile_al_cr1', percentile_al_cr1 || 0);

        }
    }
});

