frappe.ui.form.on("Final Purchase Request", {
    retrieve_data: function(frm) {
        if (!frm.doc.start_date_purchase_requisition || !frm.doc.end_date_purchase_requisition) {
            frappe.msgprint(__('กรุณากรอกวันที่เริ่มต้นและวันที่สิ้นสุด')); // แจ้งเตือนเมื่อไม่ได้กรอกวันที่
            return;
        }

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Parcel Purchase Request',
                filters: [
                    ["wf_ppr_state", "=", "อนุมัติการขอซื้อ"],
                    ["posting_date", ">=", frm.doc.start_date_purchase_requisition],
                    ["posting_date", "<=", frm.doc.end_date_purchase_requisition],
                    ["is_pr", "=", "ไม่มีบริษัท"]
                ],
                fields: ["name"], // ดึงเฉพาะชื่อเอกสาร
                limit_page_length: 1000
            },
            callback: function(response) {
                var requests = response.message;
                if (requests && requests.length > 0) {
                    frm.clear_table("final_purchase_request_table");
                    requests.forEach(function(request) {
                        frappe.model.with_doc("Parcel Purchase Request", request.name, function() {
                            var parcel_purchase_request = frappe.model.get_doc("Parcel Purchase Request", request.name);

                            if (parcel_purchase_request.parcel_purchase_request_tabel) {
                                $.each(parcel_purchase_request.parcel_purchase_request_tabel, function(index, row) {
                                    var d = frm.add_child("final_purchase_request_table");
                                    d.purchase_request_no = request.name;
                                    d.product_code = row.product_code;
                                    d.product_list = row.product_list;
                                    d.qty_approved = row.qty_approved;
                                    d.unit = row.unit;
                                    d.department = parcel_purchase_request.department;
                                    d.estimate = row.price;
                                    d.actual_purchase_qty = row.qty_approved;
                                });
                            }
                            frm.refresh_field("final_purchase_request_table");
                        });
                    });
                } else {
                    frappe.msgprint(__('ไม่พบข้อมูลในช่วงวันที่ที่ระบุ')); // แจ้งเตือนเมื่อไม่พบข้อมูล
                }
            }
        });
    },

    setup: function(frm) {
        frm.set_query("parcel_purchase_request", function() {
            return {
                filters: [
                    ["Parcel Purchase Request", "wf_ppr_state", "=", "อนุมัติการขอซื้อ"]
                ]
            };
        });
    }
});


frappe.ui.form.on('Final Purchase Request', {
    validate: function(frm) {
        // Loop ผ่านทุกแถวในตาราง
        frm.doc.final_purchase_request_table.forEach(function(row) {
            // ตรวจสอบว่าค่า qty_approved และ estimate มีอยู่
            if (row.qty_approved && row.estimate) {
                row.total_money = row.qty_approved * row.estimate;
            } else {
                row.total_money = 0; // ตั้งค่าเป็น 0 หากข้อมูลไม่ครบ
            }
        });
    }
});


frappe.ui.form.on('Final Purchase Request', {
    after_workflow_action: function(frm) {
        console.log("Workflow Action Triggered: Current wf_fpr_state =", frm.doc.wf_fpr_state);

        // ตรวจสอบสถานะ wf_fpr_state และกำหนดค่าที่เหมาะสมสำหรับ wf_ppr_state
        let new_state;
        if (['ยกเลิก'].includes(frm.doc.wf_fpr_state)) {
            new_state = 'อนุมัติการขอซื้อ';
        } else if (['ประมาณการแล้ว'].includes(frm.doc.wf_fpr_state)){
            new_state = 'ซื้อของแล้ว';
        }

        // หากสถานะใหม่ถูกกำหนด
        if (new_state) {
            console.log("Processing final_purchase_request_table...");
            
            frm.doc.final_purchase_request_table.forEach(row => {
                if (row.purchase_request_no) {
                    console.log(`Updating Parcel Purchase Request (${row.purchase_request_no}) to "${new_state}"`);

                    // อัปเดตสถานะ wf_ppr_state ใน Parcel Purchase Request
                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: 'Parcel Purchase Request',
                            name: row.purchase_request_no,
                            fieldname: 'wf_ppr_state',
                            value: new_state
                        },
                        callback: function(response) {
                            if (!response.exc) {
                                console.log(`Successfully updated Parcel Purchase Request: ${row.purchase_request_no}`);
                            } else {
                                console.error(`Failed to update Parcel Purchase Request: ${row.purchase_request_no}`, response.exc);
                            }
                        }
                    });
                }
            });
        } else {
            console.log("No action taken: wf_fpr_state does not match any specified condition.");
        }
    }
});

