                ]
            };
        };
    },
    product_type: function (frm) {
        let today = frappe.datetime.get_today(); // ดึงวันที่ปัจจุบัน
        let yearCE = today.split("-")[0]; // ได้ค่าปี ค.ศ.
        let yearTH = parseInt(yearCE) + 543; // แปลงเป็น พ.ศ.
        let month = today.split("-")[1]; // ได้ค่าเดือน MM

        // ตั้งค่า naming_series ตาม product_type
        if (frm.doc.product_type === 'ยา') {
            frm.set_value('naming_series', `SEH-PHA_.###./${yearTH}`);  // เพิ่มจุดหลัง ###
        } else if (frm.doc.product_type === 'เวชภัณฑ์ที่ไม่ใช่ยา' || frm.doc.product_type === 'อื่น ๆ') {
            frm.set_value('naming_series', `PH${yearTH}${month}.###`);
        }
    },
    before_save: function (frm) {
        // ตรวจสอบว่า naming_series มีค่าหรือไม่
        if (!frm.doc.naming_series) {
            frappe.throw(__('Please select a valid type for naming series'));
