frappe.ui.form.on('Eyeglasses Information', {
    onload: function (frm) {
        // ตั้งค่า Query Filter สำหรับฟิลด์ type
        frm.fields_dict['type'].get_query = function () {
            return {
                filters: [
                    ['type', 'in', ['แว่นตา', 'สร้อยแว่น', 'เลนส์', 'น้ำยาเช็ดเลนส์', 'คอนแทคเลนส์', 'น้ำยาแช่คอนแทคเลนส์', 'ตลับคอนแทคเลนส์', 'สกรู', 'ซิลิโคนขาแว่น']]
                ]
            };
        };
    },
    type: function (frm) {
        if (frm.doc.type === 'แว่นตา') {
            frm.set_value('naming_series', 'G.YY.MM.###'); 
        } else if (frm.doc.type === 'สร้อยแว่น') {
            frm.set_value('naming_series', 'GC.YYYY.MM.###');
        } else if (frm.doc.type === 'น้ำยาเช็ดเลนส์') {
            frm.set_value('naming_series', 'LC.YYYY.MM.###');
        } else if (frm.doc.type === 'คอนแทคเลนส์') {
            frm.set_value('naming_series', 'CL.YYYY.MM.###');
        } else if (frm.doc.type === 'น้ำยาแช่คอนแทคเลนส์') {
            frm.set_value('naming_series', 'CLQ-Eye.YYYY.MM.###');
        } else if (frm.doc.type === 'ตลับคอนแทคเลนส์') {
            frm.set_value('naming_series', 'CLC.YYYY.MM.###');
        } else if (frm.doc.type === 'สกรู') {
            frm.set_value('naming_series', 'SC.YYYY.MM.###');
        } else if (frm.doc.type === 'ซิลิโคนขาแว่น') {
            frm.set_value('naming_series', 'SGL.YYYY.MM.###');
        } else if (frm.doc.type === 'เลนส์') {
            if (frm.doc.lens_types && frm.doc.eyesight) {
                let lens_code = frm.doc.lens_types.replace(/\s/g, '').toUpperCase(); // ลบช่องว่างและแปลงเป็นตัวใหญ่
                let eyesight_code = frm.doc.eyesight.replace(/\s/g, ''); // ลบช่องว่าง
                frm.set_value('naming_series', `${eyesight_code}${lens_code}.##`);
            } else {
                frm.set_value('naming_series', 'LEN'); // fallback ถ้าไม่มีค่า
            }
        }
    },
    before_save: function(frm) {
        if (!frm.doc.naming_series) {
            frappe.throw(__('Please select a valid type for naming series'));
        }
    },
    lens_types: function(frm) {
        if (frm.doc.type === 'เลนส์' && frm.doc.lens_types && frm.doc.eyesight) {
            let lens_code = frm.doc.lens_types.replace(/\s/g, '').toUpperCase();
            let eyesight_code = frm.doc.eyesight.replace(/\s/g, '');
            frm.set_value('naming_series', `${eyesight_code}${lens_code}.##`);
        }
    },
    eyesight: function(frm) {
        if (frm.doc.type === 'เลนส์' && frm.doc.lens_types && frm.doc.eyesight) {
            let lens_code = frm.doc.lens_types.replace(/\s/g, '').toUpperCase();
            let eyesight_code = frm.doc.eyesight.replace(/\s/g, '');
            frm.set_value('naming_series', `${eyesight_code}${lens_code}.##`);
        }
    }
});




