function calculate_discounted_price(frm) {
    let selling_price = frm.doc.selling_price || 0;
    let percent = frm.doc.percent || 0;

    // ถ้า percent เป็น 0 ให้ price_discount เป็น 0 ทันที
    let price_discount = percent === 0 ? 0 : selling_price - (selling_price * percent) / 100;

    frm.set_value('price_discount', price_discount);
}

