        calculate_bedtime(frm);
    },
    wf_ipd_state: function(frm) {
        calculate_bedtime(frm);
    }
});

function calculate_bedtime(frm) {
    if (frm.doc.wf_ipd_state === "Discharge" && frm.doc.date_admit_ward && frm.doc.discharge_date) {
        let admit_date = frappe.datetime.str_to_obj(frm.doc.date_admit_ward);
        let discharge_date = frappe.datetime.str_to_obj(frm.doc.discharge_date);
        
        let diff_days = frappe.datetime.get_day_diff(discharge_date, admit_date);
        
        frm.set_value('number_days_bedtime', diff_days === 0 ? 1 : diff_days);
    } else {
        frm.set_value('number_days_bedtime', 0);
    }
}

frappe.ui.form.on("Eyeglass Registration Form", {
    retrieve_data: function(frm) {
        if (!frm.doc.start_date_eyeglass_registration || !frm.doc.end_date_eyeglass_registration) {
            frappe.msgprint(__('กรุณากรอกวันที่เริ่มต้นและวันที่สิ้นสุด'));
            return;
        }

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Eyeglasses Information',
                filters: [
                    ["wf_glass_state", "in", ["คงตู้", "ขายแล้ว"]],
                    ["posting_date", ">=", frm.doc.start_date_eyeglass_registration],
                    ["posting_date", "<=", frm.doc.end_date_eyeglass_registration]
                ],
                fields: ["name", "floor", "brand", "model", "selling_price", "wf_glass_state", "posting_date"], 
                order_by: "name asc",  
                limit_page_length: 10000
            },
            callback: function(response) {
                var requests = response.message;

                if (requests && requests.length > 0) {
                    frm.clear_table("eyeglass_registration_form_table");

                    // ✅ เรียง requests อีกรอบ เพื่อความชัวร์
                    requests.sort((a, b) => a.name.localeCompare(b.name));

                    requests.forEach(function(request) {
                        var d = frm.add_child("eyeglass_registration_form_table");
                        d.glass_code = request.name;
                        d.brand = request.brand;
                        d.model = request.model;
                        d.selling_price = request.selling_price;
                        d.floor = request.floor;
                        d.status = request.wf_glass_state;
                        d.posting_date = request.posting_date;
                    });

                    frm.refresh_field("eyeglass_registration_form_table");
                } else {
                    frappe.msgprint(__('ไม่พบข้อมูลในช่วงวันที่ที่ระบุ'));
                }
            }
        });
    },
});


