frappe.ui.form.on('Healthcare Staff Meeting Recap', {
    before_save: function(frm) {
        let today = frappe.datetime.get_today();
        let year = moment(today).format('YYYY'); // ปี ค.ศ.
        let thai_year = parseInt(year) + 543; // แปลงเป็น พ.ศ.

        let start_number = 8; // กำหนดค่าเริ่มต้นของปีแรก

        // ค้นหาเอกสารล่าสุดของปีปัจจุบัน
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Healthcare Staff Meeting Recap",
                filters: [
                    ["name_naming", "like", `MSO-%/${thai_year}`] // หาข้อมูลของปีปัจจุบันที่ขึ้นต้นด้วย MSO-
                ],
                fields: ["name_naming"],
                order_by: "creation desc",
                limit_page_length: 1
            },
            callback: function(response) {
                let last_number = start_number - 1; // เริ่มจาก 8 แต่ถ้าไม่มีเอกสาร ให้ใช้ 7 แล้วบวก 1 

                if (response.message.length > 0) {
                    let last_entry = response.message[0].name_naming;
                    let last_num = last_entry.split("/")[0].replace("MSO-", ""); // ตัด MSO- ออกแล้วดึงเลขหน้า
                    last_number = parseInt(last_num) || start_number - 1;
                }
                
                let new_number = last_number + 1;
                let formatted_number = String(new_number).padStart(3, '0'); // เติม 0 ข้างหน้าให้ครบ 3 หลัก
                let new_name = `MSO-${formatted_number}/${thai_year}`;

                frm.set_value("name_naming", new_name);
            }
        });
    }
});



