                        let updated_qty_remaining_stock = (r.message.qty_remaining_stock || 0) + row.qty;

                        frappe.db.set_value('Eyeglasses Information', row.barcode, {
                            'qty_remaining_stock': updated_qty_remaining_stock
                        }).then(() => {
                            frappe.msgprint({
