    after_cancel: function(frm) {
        frm.doc.accepting_stock_eyeglass_room_table.forEach(function(row) {
            frappe.db.get_value('Eyeglasses Information', { 'name': row.barcode }, ['qty_remaining_stock'])
                .then(r => {
                    if (r && r.message) {
                        let current_stock = r.message.qty_remaining_stock || 0;
                        let updated_qty_remaining = current_stock - row.qty;
                        updated_qty_remaining = Math.max(updated_qty_remaining, 0); // ป้องกันค่าติดลบ
                        

                        frappe.db.set_value('Eyeglasses Information', row.barcode, {
                            'qty_remaining_stock': updated_qty_remaining
                        }).then(() => {
                            frappe.msgprint({
                                message: `<span style="color: orange;">ยกเลิกรายการ: ${row.barcode || 'ไม่ทราบรหัส'} จำนวน: ${row.qty || 0} อัน ถูกลบออกจากสต็อก</span>`,
