                        message: __("แว่นรายการนี้ไม่ได้อยู่ในสถานะคงตู้ กรุณาตรวจสอบอีกครั้ง"),
                        indicator: "red"
                    });
                    frm.set_value("eyeglasses_information", ""); // ล้างค่า
                    return;
                }

                // ตรวจสอบว่าตาราง eyewear_transaction_table มีข้อมูลหรือยัง ถ้าไม่มีให้กำหนดเป็นอาร์เรย์ว่าง
                if (!frm.doc.eyewear_transaction_table) {
                    frm.doc.eyewear_transaction_table = [];
                }

                // ตรวจสอบว่ามีแถวนี้อยู่ในตารางแล้วหรือไม่
                let exists = frm.doc.eyewear_transaction_table.some(row => row.barcode === eyeglasses_information.name);

                if (!exists) {
                    // เพิ่มแถวใหม่ใน Child Table
                    let new_row = frm.add_child("eyewear_transaction_table");
                    new_row.barcode = eyeglasses_information.name;
                    new_row.brand = eyeglasses_information.brand;
                    new_row.model = eyeglasses_information.model;
                    new_row.locker = eyeglasses_information.locker;
                    new_row.floor = eyeglasses_information.floor;
                    new_row.selling_price = eyeglasses_information.selling_price;
                    new_row.price_discount = eyeglasses_information.price_discount;
                    

                    // คำนวณ actual_selling_price ตามเงื่อนไขที่ต้องการ
                    if (new_row.price_discount) {
                        new_row.actual_selling_price = new_row.price_discount;
                    } else if (!new_row.price_discount){
                        new_row.actual_selling_price = new_row.selling_price - new_row.price_discount;
                    }

                    new_row.discount = new_row.price_discount === 0 ? 0 : new_row.selling_price - new_row.price_discount;

                    // รีเฟรชตารางให้แสดงผล
