frappe.ui.form.on('Eyewear Transaction', {
    'hn': function(frm) {
        let entered_hn = frm.doc.hn ? frm.doc.hn.trim() : ''; // ตัดช่องว่างออกก่อนค้นหา

        // ตรวจสอบว่ากรอกข้อมูลหรือไม่
        if (entered_hn.length > 0) {
            // เติมเลข 0 ด้านหน้าให้ครบ 8 หลัก
            let formatted_hn = entered_hn.padStart(8, '0');

            // เรียกใช้งาน Server Script เพื่อตรวจสอบข้อมูล
            frappe.call({
                method: 'erpnext.visit_hn_myopia.fetch_Name_from_tblpatientbasicdata',
                args: {
                    entered_hn: formatted_hn // ส่งค่า HN ที่กรอกไปตรวจสอบ
                },
                callback: function(r) {
                    if (r.message) {
                        // ถ้าพบข้อมูล ให้แสดงข้อมูลที่ช่อง salutation, namef, lastname และ sex
                        frm.set_value('salutation', r.message.Fname); // แสดง Fname ใน salutation
                        frm.set_value('namef', r.message.Name); // แสดง Name ใน namef
                        frm.set_value('lastname', r.message.Lastname); // แสดง Lastname ใน lastname

                        // เปลี่ยนค่า Sex เป็น ชาย หรือ หญิง
                        if (r.message.Sex === 'M') {
                            frm.set_value('gender', 'ชาย');
                        } else if (r.message.Sex === 'F') {
                            frm.set_value('gender', 'หญิง');
                        } else {
                            frm.set_value('gender', ''); // กรณีอื่นๆ
                        }

                        // แสดง Birthdate ในช่อง birthday
                        if (r.message.Birthdate) {
                            frm.set_value('birthday', r.message.Birthdate); // แสดง Birthdate
                        } else {
