frappe.ui.form.on("Eyewear Transaction", {
    birthday: function(frm) {
        if (frm.doc.birthday) {
            let birth_date = new Date(frm.doc.birthday);
            let today = new Date();
            let age = today.getFullYear() - birth_date.getFullYear();
            let month_diff = today.getMonth() - birth_date.getMonth();
            let day_diff = today.getDate() - birth_date.getDate();

            // ปรับอายุ ถ้าวันเกิดยังไม่ถึงในปีนี้
            if (month_diff < 0 || (month_diff === 0 && day_diff < 0)) {
                age--;
            }

            frm.set_value("age", age);
        }
    }
});

