frappe.ui.form.on('Eyewear Transaction', {
    after_workflow_action: function(frm) {
        
        // ตรวจสอบสถานะ wf_eyetran_state และกำหนดค่าที่เหมาะสมสำหรับ wf_glass_state
        let new_state;
        if (['ยกเลิก', 'แก้ไข'].includes(frm.doc.wf_eyetran_state)) {
            new_state = 'คงตู้';
        } else if (['ขายแล้ว'].includes(frm.doc.wf_eyetran_state)){
            new_state = 'ขายแล้ว';
        } else if (['ส่งคืนบริษัท'].includes(frm.doc.wf_eyetran_state)){
            new_state = 'ส่งคืนบริษัท';
        }

        // หากสถานะใหม่ถูกกำหนด
        if (new_state) {
            frm.doc.eyewear_transaction_table.forEach(row => {
                if ( row.type == "แว่นตา"){
                if (row.barcode) {
                    console.log(`Updating Parcel Purchase Request (${row.barcode}) to "${new_state}"`);

                    // อัปเดตสถานะ wf_glass_state ใน Parcel Purchase Request
                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: 'Eyeglasses Information',
                            name: row.barcode,
                            fieldname: 'wf_glass_state',
                            value: new_state
                        },
                        callback: function(response) {
                            if (!response.exc) {
                                console.log(`Successfully updated Parcel Purchase Request: ${row.barcode}`);
                            } else {
                                console.error(`Failed to update Parcel Purchase Request: ${row.barcode}`, response.exc);
                            }
                        }
                    });
                }
                }
            });
            
        } else {
            console.log("No action taken: does not match any specified condition.");
        }

    }
});


