                                            indicator: 'green'
                                        });
                                });
                            } 
                        }
                    });
                }
            });
        } else if (frm.doc.wf_eyetran_state === "ยกเลิก") {
            frm.doc.eyewear_transaction_table.forEach(function(row) {
                if (row.type != "แว่นตา") {
                    frappe.db.get_value('Eyeglasses Information', { 'name': row.barcode }, ['qty_remaining_stock'], (r) => {
                        if (r) {
                            // คืนจำนวนสต็อกที่ถูกตัดไปก่อนหน้านี้
                            let updated_qty_remaining = (r.qty_remaining_stock || 0) + row.qty;
            
