frappe.ui.form.on('Memorandum', {
    before_save: function (frm) {
            let today = frappe.datetime.get_today(); // วันที่ปัจจุบัน
        let yearCE = today.split("-")[0]; // ปี ค.ศ.
        let yearTH = parseInt(yearCE) + 543; // แปลงเป็น พ.ศ.

        let department = frm.doc.initials; // แผนก

        // กำหนดค่าเริ่มต้นของแต่ละแผนก (สามารถเพิ่มแผนกอื่นได้)
        let department_start_numbers = {
            "PHA": 20,
            "PUR": 10,
            "MID": 5
        };

        let start_number = department_start_numbers[department] || 1; // ถ้าไม่มีในลิสต์ให้ใช้ 1

        // ค้นหาหมายเลขล่าสุดของแผนกนี้ (เฉพาะปีปัจจุบัน)
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Memorandum",
                filters: [["naming_series", "like", `SEH-${department}.%/${yearTH}`]], // ค้นหาเฉพาะของปีนี้
                fields: ["naming_series"],
                order_by: "creation desc",
                limit_page_length: 1
            },
            callback: function (response) {
                let last_number = start_number - 1; // ตั้งค่าเริ่มต้น (ถ้าไม่มีเอกสาร)

                if (response.message.length > 0) {
                    // ถ้ามีเอกสารของปีนี้แล้ว → ใช้เลขล่าสุด +1
                    let last_entry = response.message[0].naming_series;
                    let last_num = last_entry.split(".")[1].split("/")[0]; // ดึงเลขรันที่อยู่ระหว่าง `.` และ `/`
                    last_number = parseInt(last_num) || start_number - 1;
                } 

                let new_number = last_number + 1; // เพิ่มเลขรัน
                let formatted_number = String(new_number).padStart(3, '0'); // เติม 0 ให้ครบ 3 หลัก
                let new_naming_series = `SEH-${department}.${formatted_number}/${yearTH}`;

                frm.set_value("naming_series", new_naming_series);
            }
        });
    }
});

