function update_html_display(frm) {
    let payment_amount = Number(frm.doc.payment_amount) || 0;
    let outstanding_balance = Number(frm.doc.outstanding_balance) || 0;

    let message = `
        <center>
            <p style="color: blue; font-size: 20px; font-family: Tahoma;">กรุณาระบุยอดชำระ</p>
        </center>
    `;

    if (payment_amount && outstanding_balance) {
        if (payment_amount !== outstanding_balance) {
            message = `
                <center>
                    <img src="/files/incorrect.png" style="width: 100px; height: 100px; margin-right: 10px;">
                    <p style="color: red; font-size: 20px; font-family: Tahoma;">ยังมียอดค้างชำระ</p>
                </center>
            `;
        } else {
            message = `
                <center>
                    <img src="/files/check-mark.png" style="width: 100px; height: 100px; margin-right: 10px;">
                    <p style="color: green; font-size: 20px; font-family: Tahoma;">ไม่มียอดค้างชำระ</p>
                </center>
            `;
        }
    }

    frm.set_df_property('html_display', 'options', message);
}

frappe.ui.form.on("Payment Deposit Deduction", {
	setup: function(frm) {
		frm.set_query("bill_sale", function() {
			return {
				filters: [
					["Eyewear Transaction","wf_eyetran_state", "=", "มัดจำ" ]
				]
			}
		});
	}
});


frappe.ui.form.on('Payment Deposit Deduction', {
    after_workflow_action: function(frm) {
        let new_state;
        if (frm.doc.wf_pdd_state === 'เสร็จสิ้น') {
            new_state = 'รับแว่นแล้ว';
        }

        // ตรวจสอบว่ามีสถานะใหม่ และ `bill_sale` ไม่เป็นค่าว่าง
        if (new_state && frm.doc.bill_sale) {
            // ดึงชื่อเต็มของผู้ใช้ที่ล็อกอินอยู่
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'User',
                    filters: { name: frappe.session.user },
                    fieldname: 'full_name'
                },
                callback: function(res) {
                    if (res.message && res.message.full_name) {
                        let full_name = res.message.full_name;

                        // อัปเดตสถานะและฟิลด์ที่เกี่ยวข้องใน Eyewear Transaction
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: {
                                doctype: 'Eyewear Transaction',
                                name: frm.doc.bill_sale,
                                fieldname: {
                                    'wf_eyetran_state': new_state,
                                    'get_glasses_date': frappe.datetime.get_today(), // วันที่ปัจจุบัน
                                    'get_glasses_time': frappe.datetime.now_time(),  // เวลาปัจจุบัน
                                    'fullname_get_glasses': full_name // ชื่อของผู้ที่ล็อกอิน
                                }
                            },
                            callback: function(response) {
                                if (!response.exc) {
                                    console.log(`Successfully updated Eyewear Transaction`);
                                } else {
                                    console.error(`Failed to update Eyewear Transaction`, response.exc);
                                }
                            }
                        });
                    } else {
                        console.error("Failed to fetch full name for logged-in user.");
                    }
                }
            });
        } else {
            console.log("No action taken: Missing bill_sale or invalid state.");
        }
    }
});
